/* Local downloads: no session or server request is needed for generated files. */
const DataExport = (()=>{
 const xml=v=>String(v??'').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c])).replace(/\r?\n/g,'&#10;');
 const dataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('파일을 읽지 못했습니다.'));r.readAsDataURL(blob);});
 async function download(blob,name){
  if(window.webkit?.messageHandlers?.nismlWorkspace){
   const bridge=window.webkit?.messageHandlers?.nismlQtiPlot,ready=bridge&&await bridge.postMessage({action:'status'});
   if(!ready||ready.bridgeVersion<9)throw Error('QTI·테이블 저장은 Mac용 Hub 0.5.1로 업데이트한 뒤 이용해 주세요.');
   const result=await bridge.postMessage({action:'export',name,base64:(await dataURL(blob)).split(',')[1]});return !result.cancelled;
  }
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);return true;
 }
 async function png(svg){const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('PNG 이미지 변환에 실패했습니다.'));dataURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'})).then(url=>image.src=url,reject);});const c=document.createElement('canvas');c.width=image.naturalWidth*2;c.height=image.naturalHeight*2;if(c.width*c.height>32000000)throw Error('PNG가 너무 큽니다. 행 수나 표 너비를 줄여 주세요.');const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(image,0,0,c.width,c.height);return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('PNG 생성에 실패했습니다.')),'image/png'));}
 function qti(parsed,raw){
  const s=DataPlot.normalize(raw);DataPlot.svg(parsed,s);const cols=DataPlot.seriesColumns(parsed),dual=Number.isInteger(parsed.x2Index);
  const range=(vs,lo,hi,zero=false)=>{let a=vs.reduce((a,v)=>Math.min(a,v),Infinity),b=vs.reduce((a,v)=>Math.max(a,v),-Infinity);if(zero){a=Math.min(0,a);b=Math.max(0,b);}const pad=a===b?(Math.abs(a)*.1||1):(b-a)*.05;a-=pad;b+=pad;return [lo===''?a:Number(lo),hi===''?b:Number(hi)];};
  const ranges=secondary=>{const c=cols.filter(v=>v.secondary===secondary),p=c.flatMap(v=>parsed.data.filter(r=>r[v.xcol]!=null&&r[v.col]!=null).map(r=>[r[v.xcol],r[v.col]])),k=secondary?'2':'';return {x:range(p.map(v=>v[0]),s['x'+k+'min'],s['x'+k+'max']),y:range(p.map(v=>v[1]),s['y'+k+'min'],s['y'+k+'max'],s.type==='bar')};};
  const r1=ranges(false),r2=dual?ranges(true):r1,F=s.font,left=F*4+40,top=dual?F*3+40:80,W=left+s.width+(dual?F*4+40:50),H=top+s.height+F*3+60;
  const font=`Arial,-1,${F},5,75,0,0,0,0,0`;
  const axis=(id,r,title,labels)=>`<axis id="${id}" on="1" type="0" format="0" prec="6" lw="2"><div from="${r[0]}" to="${r[1]}" step="${(r[1]-r[0])/5}" maj="6" min="4" type="0"/><ticks maj="3" majl="12" min="3" minl="7"/><title text="${xml(title)}" color="#111111" font="${font}" align="5124" space="10"/>${labels?`<labels space="4" font="${font}" align="0"/>`:''}</axis>`;
  return `<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE qti>\n<qti app="QtiPlot" version="1.0.0-rc17" dpi="72" arch="Mac64" script="Python" windows="2" expand="1"><window type="1" name="HubData" x="0" y="0" w="600" h="400"><tab rows="${parsed.data.length}" cols="${parsed.names.length}" labels="0">${parsed.names.map((n,i)=>`<col name="C${i+1}" comment="${xml(n)}" type="6" num="0" prec="13" plot="${i===0||i===parsed.x2Index?1:2}" width="120" stat="0" data="${parsed.data.map(row=>row[i]==null?'':row[i]).join(';')};"/>`).join('')}</tab></window><window type="3" name="Graph1" x="0" y="0" w="${W}" h="${H+60}" active="1" dpi="72"><layout cw="${W}" ch="${H}" w="${s.width}" h="${s.height}" left="5" right="5" top="5" bottom="5" rows="1" cols="1" vSpace="5" hSpace="5" hAlign="0" vAlign="0" align="0" common="0" link="0" scale="0" currentLayer="0" sPrint="0" cmPrint="0" atUnits="1" atdIndex="0" atPolicy="4" alMode="0" luMode="2"/><tab x="0" y="0" w="${W}" h="${H}" autoscale="0" maxMajorTicks="20" axesLayout="0" antialias="1" gap="1" scaleFont="0" dataMargins="0"><page x="0" y="0" w="1" h="1"/><title text="${xml(s.title)}" color="#111111" font="${font}" align="4228"/><frame bg="#ffffff,0"/><canvas x="${left}" y="${top}" w="${s.width}" h="${s.height}" fixRatio="0" bg="#ffffff,0"/>
  ${cols.map((c,i)=>{const cfg=s.series[i]||{},color=/^#[0-9a-f]{6}$/i.test(cfg.color)?cfg.color:DataPlot.colors[i%6],shape=cfg.shape||'circle',symbol=s.type!=='lineonly'&&s.type!=='bar'&&shape!=='none',type=s.type==='bar'?3:s.type==='scatter'?1:symbol?2:0;return `<curve type="${type}" z="${21+i}" table="HubData" x="C${c.xcol+1}" y="C${c.col+1}" from="0" to="-1" line="${s.type==='scatter'?0:1}" lc="${color}" lw="${s.line}" ls="0" brc="${color}" brs="${s.type==='bar'?1:0}"${s.type==='bar'?` gap="70" offset="${(i-(cols.length-1)/2)*100}"`:''}${c.secondary?' xAxis="3" yAxis="1"':''}>${symbol?`<symbol style="${({circle:0,square:1,diamond:2,triangle:3,cross:9})[shape]??0}" size="${s.marker}" lc="${color}" lw="1" ls="0" brc="${color}"/>`:''}</curve>`;}).join('')}
  ${axis(0,r1.y,s.yLabel,true)}${axis(1,r2.y,dual?s.y2Label:'',dual)}${axis(2,r1.x,s.xLabel,true)}${axis(3,r2.x,dual?s.x2Label:'',dual)}<item type="2" x="${r1.x[0]+(r1.x[1]-r1.x[0])*(s.legendX??.65)}" y="${r1.y[1]-(r1.y[1]-r1.y[0])*(s.legendY??.05)}" frame="0" lc="#000000" lw="1" ls="0" bg="#ffffff,0" onTop="1" at="0" on="1" auto="0" font="Arial,-1,${s.legendFont},5,50,0,0,0,0,0" left="10" top="5" symbLineLength="32" symbLineWidth="-1" text="${xml(cols.map((c,i)=>'\\l('+(i+1)+') '+c.name).join('\n'))}"/></tab></window></qti>`;
 }
 return {xml,dataURL,download,png,qti};
})();
